package com.kishar.app;import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.security.keystore.*;import android.util.Base64;import java.util.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import okhttp3.*;import org.json.*;public class MainActivity extends Activity{ final int OLIVE=Color.rgb(105,132,67),INK=Color.rgb(25,28,24),BG=Color.rgb(248,249,246),RED=Color.rgb(173,55,45); LinearLayout body;OkHttpClient http;WebSocket socket;Timer heartbeatTimer;boolean connected=false,simulation=true;long seq=0;String server="",robotId="",token=""; int d(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} TextView tx(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(d(14),d(10),d(14),d(10));return v;} Button bt(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(INK);b.setAllCaps(false);b.setMinHeight(d(52));return b;} void add(View v){body.addView(v,new LinearLayout.LayoutParams(-1,-2));} void title(String s){TextView v=tx(s,25,INK);v.setTypeface(null,1);add(v);} void card(String s){TextView v=tx(s,16,INK);v.setBackgroundColor(Color.WHITE);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,d(5),0,d(5));body.addView(v,p);} void frame(){body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(d(16),d(8),d(16),d(16));body.setBackgroundColor(BG);ScrollView s=new ScrollView(this);s.addView(body);setContentView(s);} void clear(String s){body.removeAllViews();title(s);} void back(){Button b=bt("رجوع للرئيسية");b.setOnClickListener(v->home());add(b);} void stop(){sendTool("stop_robot",new JSONObject());} void emergency(){Button b=bt("إيقاف طوارئ");b.setTextColor(Color.WHITE);b.setBackgroundColor(RED);b.setOnClickListener(v->{stop();Toast.makeText(this,connected?"تم إرسال STOP إلى الخادم":"لا يوجد اتصال — تم إيقاف المحاكي",1).show();});add(b);} public void onCreate(Bundle b){super.onCreate(b);load();home();} String keyAlias="kishar_config";
 javax.crypto.SecretKey cryptoKey() throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(keyAlias)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(keyAlias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return((KeyStore.SecretKeyEntry)ks.getEntry(keyAlias,null)).getSecretKey();}
 String protect(String s){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,cryptoKey());String iv=Base64.encodeToString(c.getIV(),Base64.NO_WRAP);String data=Base64.encodeToString(c.doFinal(s.getBytes("UTF-8")),Base64.NO_WRAP);return iv+"."+data;}catch(Exception e){return"";}}
 String reveal(String s){try{String[] a=s.split("\.");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,cryptoKey(),new GCMParameterSpec(128,Base64.decode(a[0],Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(a[1],Base64.NO_WRAP)),"UTF-8");}catch(Exception e){return"";}}
 void load(){android.content.SharedPreferences p=getSharedPreferences("kishar_secure",0);server=reveal(p.getString("server",""));robotId=reveal(p.getString("robot",""));token=reveal(p.getString("token",""));simulation=p.getBoolean("sim",true);}
 void save(){getSharedPreferences("kishar_secure",0).edit().putString("server",protect(server)).putString("robot",protect(robotId)).putString("token",protect(token)).putBoolean("sim",simulation).apply();}
 void startHeartbeat(){stopHeartbeat();heartbeatTimer=new Timer();heartbeatTimer.scheduleAtFixedRate(new TimerTask(){public void run(){if(connected)sendFrame("HEARTBEAT",new JSONObject());}},0,1000);}
 void stopHeartbeat(){if(heartbeatTimer!=null){heartbeatTimer.cancel();heartbeatTimer=null;}} void home(){frame();TextView h=tx("Kishar 🔥",28,OLIVE);h.setTypeface(null,1);add(h);card("اتصال فعلي بخادم NVIDIA عبر WebSocket\nالحالة: "+(connected?"متصل":"غير متصل")+"\nالوضع: "+(simulation?"محاكاة":"حقيقي")+"\nRobot ID: "+(robotId.isEmpty()?"غير محدد":robotId));  Button c=bt(connected?"قطع الاتصال":"اتصال بالخادم");c.setOnClickListener(v->{if(connected)disconnect();else connect();});add(c);  Button mode=bt(simulation?"تفعيل الوضع الحقيقي":"العودة إلى المحاكاة");mode.setOnClickListener(v->{simulation=!simulation;save();home();});add(mode);  Button o=bt("غرفة العمليات");o.setOnClickListener(v->ops());add(o);Button m=bt("التحكم اليدوي");m.setOnClickListener(v->manual());add(m);Button chat=bt("إرسال أمر إلى Joker");chat.setOnClickListener(v->chat());add(chat);Button set=bt("إعدادات الاتصال والروبوت");set.setOnClickListener(v->settings());add(set);emergency();} void connect(){if(server.isEmpty()){settings();Toast.makeText(this,"أدخل عنوان WebSocket أولًا",1).show();return;}if(!simulation&&!server.startsWith("wss://")){Toast.makeText(this,"الوضع الحقيقي يتطلب wss:// مشفرًا",1).show();return;}try{Request.Builder rb=new Request.Builder().url(server);if(!token.isEmpty())rb.addHeader("Authorization","Bearer "+token);http=new OkHttpClient.Builder().pingInterval(1,java.util.concurrent.TimeUnit.SECONDS).build();socket=http.newWebSocket(rb.build(),new WebSocketListener(){public void onOpen(WebSocket w,Response r){socket=w;connected=true;startHeartbeat();runOnUiThread(()->{Toast.makeText(MainActivity.this,"تم الاتصال الحقيقي",1).show();home();});sendHello();}public void onMessage(WebSocket w,String text){runOnUiThread(()->Toast.makeText(MainActivity.this,"وصلت رسالة من الروبوت",0).show());}public void onClosing(WebSocket w,int code,String reason){stopHeartbeat();connected=false;runOnUiThread(()->home());}public void onFailure(WebSocket w,Throwable t,Response r){stopHeartbeat();connected=false;runOnUiThread(()->{Toast.makeText(MainActivity.this,"فشل الاتصال: "+t.getMessage(),1).show();home();});}});}catch(Exception e){Toast.makeText(this,"عنوان الاتصال غير صحيح",1).show();}} void sendHello(){try{JSONObject p=new JSONObject();p.put("client","Kishar");p.put("version","0.5.0");sendFrame("HELLO",p);}catch(Exception e){}} void disconnect(){stopHeartbeat();if(socket!=null)socket.close(1000,"user");socket=null;connected=false;if(http!=null)http.dispatcher().cancelAll();home();} void sendTool(String tool,JSONObject args){try{JSONObject p=new JSONObject();p.put("tool",tool);p.put("arguments",args);sendFrame("COMMAND",p);}catch(Exception e){}} void sendFrame(String type,JSONObject payload){try{JSONObject f=new JSONObject();f.put("type",type);f.put("message_id",UUID.randomUUID().toString());f.put("robot_id",robotId);f.put("sequence",++seq);f.put("timestamp_ms",System.currentTimeMillis());f.put("expires_at_ms",System.currentTimeMillis()+1500);f.put("payload",payload);if(connected&&socket!=null)socket.send(f.toString());else if(simulation)Toast.makeText(this,"محاكاة: "+type,0).show();}catch(Exception e){}} void ops(){clear("غرفة العمليات");card("حالة الاتصال: "+(connected?"متصل فعليًا":"غير متصل")+"\nالروبوت: "+robotId+"\nالكاميرا والصوت والTelemetry تظهر عند إرسال Gateway لبياناتها.");card("ACK الأخير: —\nالبطارية: —\nIMU: —\nالمهمة: لا توجد");back();emergency();} void chat(){clear("محادثة Joker");card("الأوامر تُرسل إلى الخادم عبر COMMAND وتنتظر ACK. لا يوجد نجاح وهمي.");EditText e=new EditText(this);e.setHint("اكتب الأمر بالعربية");add(e);Button b=bt("إرسال إلى الخادم");TextView out=tx("",16,INK);b.setOnClickListener(v->{String q=e.getText().toString().trim();if(q.isEmpty()){out.setText("اكتب أمرًا.");return;}try{JSONObject p=new JSONObject();p.put("text",q);sendFrame("INTENT",p);out.setText(connected?"تم إرسال INTENT وننتظر ACK":"لا يوجد اتصال فعلي؛ شغّل المحاكاة أو اتصل بالخادم");}catch(Exception x){}});add(b);add(out);back();emergency();} void manual(){clear("التحكم اليدوي");card("Dead-Man: يستمر الأمر أثناء الضغط فقط، وعند رفع الإصبع يُرسل STOP.");GridLayout g=new GridLayout(this);g.setColumnCount(2);String[] ns={"أمام","خلف","يسار","يمين"};for(String n:ns){Button b=bt(n);b.setOnTouchListener((v,e)->{if(e.getAction()==0){try{JSONObject a=new JSONObject();a.put("distance_mm",n.equals("أمام")?300:-300);sendTool("move_linear",a);}catch(Exception x){}b.setText(n+" — يعمل");return true;}if(e.getAction()==1||e.getAction()==3){stop();b.setText(n);return true;}return true;});GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=d(60);p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);g.addView(b,p);}body.addView(g);Button s=bt("STOP");s.setTextColor(Color.WHITE);s.setBackgroundColor(RED);s.setOnClickListener(v->stop());add(s);back();emergency();} void settings(){clear("إعدادات الاتصال");card("أدخل رابط WebSocket الحقيقي، مثل wss://server.example/ws. لا تضع مفاتيحك داخل التطبيق المنشور.");EditText h=new EditText(this);h.setHint("wss:// عنوان الخادم المشفر فقط");h.setText(server);add(h);EditText r=new EditText(this);r.setHint("Robot ID");r.setText(robotId);add(r);EditText t=new EditText(this);t.setHint("Bearer Token أو مفتاح المصادقة");t.setText(token);t.setInputType(129);add(t);Button s=bt("حفظ واختبار الاتصال");s.setOnClickListener(v->{server=h.getText().toString().trim();robotId=r.getText().toString().trim();token=t.getText().toString().trim();simulation=false;save();connect();});add(s);card("المطلوب من الخادم: HELLO وCOMMAND وACK وHeartbeat. التطبيق لا يغيّر بروتوكول الخادم تلقائيًا.");back();emergency();}}
